using System;using System.IO;using System.Collections.Generic;
public static class BibliographySnapshot {
 public static Dictionary<string,object> Capture(object document,string path){dynamic d=document;File.WriteAllText(path,(string)d.WordOpenXML);var fields=new List<object>();
 foreach(dynamic first in d.StoryRanges){dynamic story=first;while(story!=null){foreach(dynamic f in story.Fields){fields.Add(new Dictionary<string,object>{{"story",(int)story.StoryType},{"type",(int)f.Type},{"code",(string)f.Code.Text},{"locked",(bool)f.Locked},{"result",(string)f.Result.Text}});}story=story.NextStoryRange;}}
 var names=new List<object>();for(int i=1;i<=9;i++){dynamic st=d.Styles.Item(-1-i);names.Add(new Dictionary<string,object>{{"level",i},{"name_local",(string)st.NameLocal},{"builtin",(bool)st.BuiltIn}});}
 var paras=new List<object>();foreach(dynamic p in d.Paragraphs){paras.Add(new Dictionary<string,object>{{"text",(string)p.Range.Text},{"outline_level",(int)p.OutlineLevel},{"list_string",(string)p.Range.ListFormat.ListString}});}
 var forms=new List<object>();foreach(dynamic f in d.FormFields){forms.Add(new Dictionary<string,object>{{"name",(string)f.Name},{"type",(int)f.Type},{"result",(string)f.Result},{"start",(int)f.Range.Start},{"end",(int)f.Range.End}});}var tableRanges=new List<object>();foreach(dynamic table in d.Tables){tableRanges.Add(new Dictionary<string,object>{{"start",(int)table.Range.Start},{"end",(int)table.Range.End},{"rows",(int)table.Rows.Count},{"text",(string)table.Range.Text}});}var sections=new List<object>();foreach(dynamic sec in d.Sections){dynamic pn=sec.Footers.Item(1).PageNumbers;sections.Add(new Dictionary<string,object>{{"chapter",(bool)pn.IncludeChapterNumber},{"level",(int)pn.HeadingLevelForChapter},{"separator",(int)pn.ChapterPageSeparator},{"number_style",(int)pn.NumberStyle}});}
 return new Dictionary<string,object>{{"formfields",forms},{"tables",tableRanges},{"fields",fields},{"builtin_headings",names},{"paragraphs",paras},{"sections",sections},{"pages",(int)d.ComputeStatistics(2)}};}
}